/* Bootstrap 5.3.3 - Minimal offline JS for SNSU-FRMS */
(function () {
  'use strict';

  const bootstrap = {};

  // Modal functionality
  class Modal {
    constructor(element) {
      this.element = element;
      this.backdrop = null;
      this.isShown = false;
    }

    show() {
      if (this.isShown) return;
      this.isShown = true;
      this.element.style.display = 'block';
      this.element.setAttribute('aria-hidden', 'false');
      this.createBackdrop();
      document.body.classList.add('modal-open');
      this.element.focus();
    }

    hide() {
      if (!this.isShown) return;
      this.isShown = false;
      this.element.style.display = 'none';
      this.element.setAttribute('aria-hidden', 'true');
      this.removeBackdrop();
      document.body.classList.remove('modal-open');
    }

    createBackdrop() {
      this.backdrop = document.createElement('div');
      this.backdrop.className = 'modal-backdrop fade show';
      document.body.appendChild(this.backdrop);
    }

    removeBackdrop() {
      if (this.backdrop) {
        this.backdrop.remove();
        this.backdrop = null;
      }
    }
  }

  // Offcanvas functionality
  class Offcanvas {
    constructor(element) {
      this.element = element;
      this.backdrop = null;
      this.isShown = false;
    }

    show() {
      if (this.isShown) return;
      this.isShown = true;
      this.element.classList.add('show');
      this.element.style.visibility = 'visible';
      this.createBackdrop();
      document.body.classList.add('offcanvas-open');
    }

    hide() {
      if (!this.isShown) return;
      this.isShown = false;
      this.element.classList.remove('show');
      this.element.style.visibility = 'hidden';
      this.removeBackdrop();
      document.body.classList.remove('offcanvas-open');
    }

    createBackdrop() {
      this.backdrop = document.createElement('div');
      this.backdrop.className = 'offcanvas-backdrop fade show';
      this.backdrop.addEventListener('click', () => this.hide());
      document.body.appendChild(this.backdrop);
    }

    removeBackdrop() {
      if (this.backdrop) {
        this.backdrop.remove();
        this.backdrop = null;
      }
    }
  }

  // Initialize components
  document.addEventListener('DOMContentLoaded', function () {
    // Modal triggers
    document.querySelectorAll('[data-bs-toggle="modal"]').forEach(trigger => {
      trigger.addEventListener('click', function (e) {
        e.preventDefault();
        const targetId = this.getAttribute('data-bs-target');
        const modalElement = document.querySelector(targetId);
        if (modalElement) {
          const modal = new Modal(modalElement);
          modal.show();

          // Close buttons
          modalElement.querySelectorAll('[data-bs-dismiss="modal"]').forEach(btn => {
            btn.addEventListener('click', () => modal.hide());
          });
        }
      });
    });

    // Offcanvas triggers
    document.querySelectorAll('[data-bs-toggle="offcanvas"]').forEach(trigger => {
      trigger.addEventListener('click', function (e) {
        e.preventDefault();
        const targetId = this.getAttribute('data-bs-target');
        const offcanvasElement = document.querySelector(targetId);
        if (offcanvasElement) {
          const offcanvas = new Offcanvas(offcanvasElement);
          offcanvas.show();

          // Close buttons
          offcanvasElement.querySelectorAll('[data-bs-dismiss="offcanvas"]').forEach(btn => {
            btn.addEventListener('click', () => offcanvas.hide());
          });
        }
      });
    });

    // Sidebar toggle for mobile
    const sidebarToggle = document.getElementById('sidebarToggle');
    if (sidebarToggle) {
      sidebarToggle.addEventListener('click', function () {
        document.body.classList.toggle('sidebar-open');
      });
    }
  });

  // Expose to global
  window.bootstrap = bootstrap;
})();